    public static function money(int $n):string{return Content::money($n);}
    public static function productCount(int $n):string {$m=$n%100;return $n.' '.($m>=11&&$m<=14?'товаров':([1=>'товар',2=>'товара',3=>'товара',4=>'товара'][$n%10]??'товаров'));}
    public static function priceBound(string $raw):?int {
        if($raw==='')return null;
        if(!preg_match('/^(0|[1-9][0-9]{0,7})(?:[.,]([0-9]{1,2}))?$/D',$raw,$m))throw new \RuntimeException('Укажите цену в рублях, не более двух знаков после запятой.');
        return (int)$m[1]*100+(int)str_pad($m[2]??'',2,'0');
    }
    public static function policy(bool $payment=false,?string $testOrigin=null):string {
        $forms="'self'";
        // Chromium also checks redirects from submitted forms against form-action.
        if($payment){$forms.=' https://yoomoney.ru https://*.yoomoney.ru https://yookassa.ru https://*.yookassa.ru';
            if($testOrigin!==null&&preg_match('#^http://127\.0\.0\.1:([0-9]{2,5})$#D',$testOrigin,$m)&&(int)$m[1]>=1024&&(int)$m[1]<=65535)$forms.=' '.$testOrigin;
        }
        return "default-src 'self'; img-src 'self' https: data:; style-src 'self' 'unsafe-inline'; font-src 'self'; script-src 'self'; frame-ancestors 'self'; base-uri 'none'; form-action ".$forms;
    }
