        $mode=$product?'product':($page?'page':([''=>'home','catalog'=>'catalog','cart'=>'cart','checkout'=>'checkout','order'=>'order','account'=>'account'][$path]??'404'));
        $accent=preg_match('/^#[a-f0-9]{6}$/i',$s['accent']??'')?$s['accent']:'#604537';$font=($s['font']??'')==='system'?'system-ui':'GallerySans';$heading=($s['heading_font']??'')==='georgia'?'Georgia':($theme==='luxe'?'GallerySerif':'GallerySans');$collectionLink=$products[0]['collection']??'';$name=$s['site_name']??$store;$title=$product?(($product['seo_title']??'')?:$product['title']):($page?(($page['seo_title']??'')?:$page['title']):['home'=>$s['tagline']??'Вещи, с которыми хочется жить.','catalog'=>'Каталог товаров','cart'=>'Ваша корзина','checkout'=>'Оформление заказа','order'=>'Ваш заказ','account'=>'Мои заказы','404'=>'Страница не найдена'][$mode]);$desc=(($page['seo_description']??'')?:($page['excerpt']??''))?: ($product?(($product['seo_description']??'')?:mb_substr(strip_tags($product['description']),0,160)):($s['tagline']??'Предметы для внимательной жизни.'));
