        <article class="g-wrap g-product"><nav class="g-breadcrumb" aria-label="Хлебные крошки"><a href="<?= $e($href('/catalog/')) ?>">Все предметы</a><span>/</span><a href="<?= $e($href('/catalog/',['category'=>$product['category']])) ?>"><?= $e($product['category']) ?></a></nav><div class="g-product-layout"><div class="g-product-gallery"><?php if(!$product['images']): ?><div class="g-noimage">Изображения пока не добавлены</div><?php endif;foreach($product['images']as $i=>$src): ?><button class="g-zoom" type="button" data-image="<?= $e(Content::asset($src)) ?>" aria-label="Увеличить фото <?= $i+1 ?>"><img src="<?= $e(Content::asset(Content::imageUrl($src))) ?>" <?= Content::imageSet($src,'(max-width:760px) calc(100vw - 40px), 58vw') ?> alt="<?= $e($product['title']) ?>" width="512" height="512" <?= $i?'loading="lazy"':'fetchpriority="high"' ?>><span>Рассмотреть +</span></button><?php endforeach ?></div><div class="g-product-info"><span class="g-kicker"><?= $e($product['brand']) ?></span><h1><?= $e($product['title']) ?></h1><p class="g-product-price"><?= $selected?self::money((int)$selected['price']):'Нет активных вариантов' ?></p><?php if($selected): ?><form method="get"><label>Исполнение<select name="variant"><?php foreach($variants as $v): ?><option value="<?= (int)$v['id'] ?>" <?= (int)$v['id']===(int)$selected['id']?'selected':'' ?>><?= $e($v['title'].' — '.self::money((int)$v['price']).($v['stock']?'':' / нет в наличии')) ?></option><?php endforeach ?></select></label><?php if($token): ?><input type="hidden" name="snapshot" value="<?= $e($token) ?>"><?php endif ?><button class="g-small-button">Выбрать вариант</button></form><p class="g-availability"><?= $selected['stock']?'В наличии: '.(int)$selected['stock']:'Нет в наличии' ?> <span>Артикул <?= $e($selected['sku']) ?></span></p><form method="post" action="<?= $e($href('/cart/')) ?>"><input type="hidden" name="csrf" value="<?= $e($o['csrf']??'') ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="variant" value="<?= (int)$selected['id'] ?>"><label>Количество<input name="quantity" type="number" min="1" max="<?= min(99,(int)$selected['stock']) ?>" value="1" required <?= !$selected['stock']?'disabled':'' ?>></label><button class="g-button" <?= !$selected['stock']?'disabled':'' ?>><?= $selected['stock']?'Добавить в корзину':'Недоступно' ?> <span>＋</span></button></form><?php endif ?><details open><summary>О предмете</summary><div class="g-prose"><?= Content::html($product['description']) ?></div></details><details><summary>Материалы и размеры</summary><p><?= nl2br($e($product['specs'])) ?></p></details><details><summary>Получение и возврат</summary><p>Условия и стоимость выбранного способа фиксируются до подтверждения заказа.</p><a href="<?= $e($href('/delivery/')) ?>">Доставка</a> · <a href="<?= $e($href('/returns/')) ?>">Возврат</a></details></div></div></article><section class="g-wrap g-selection"><div class="g-section-head"><h2>Вам также может подойти</h2><a class="g-link" href="<?= $e($href('/catalog/')) ?>">Все товары ↗</a></div><div class="g-products"><?php $cards(array_slice(array_values(array_filter($products,fn($p)=>$p['slug']!==$product['slug'])),0,3)); ?></div></section>
        <?php elseif($mode==='page'): ?><article class="g-wrap g-editorial"><span class="g-kicker"><?= $e($store) ?> / <?= $e($page['title']) ?></span><h1><?= $e($page['title']) ?></h1><p class="g-intro"><?= $e($page['excerpt']??'') ?></p><div class="g-prose"><?= Content::html($page['content']).Content::blocks($page['blocks']??[]) ?></div><?php if($path==='contact'): foreach(['email'=>'mailto:','phone'=>'tel:']as $key=>$prefix): if(!empty($s[$key])): ?><p><a class="g-link" href="<?= $e($prefix.preg_replace($key==='phone'?'/[^+0-9]/':'/\s/','',$s[$key])) ?>"><?= $e($s[$key]) ?></a></p><?php endif;endforeach;endif ?></article>
        <?php elseif(in_array($mode,['cart','checkout','order','account'],true)): ?><section class="g-wrap g-commerce"><nav class="g-breadcrumb" aria-label="Хлебные крошки"><a href="<?= $e($href('/')) ?>">Главная</a><span>/</span><span><?= $e($title) ?></span></nav><h1><?= $e($title) ?></h1><?= $o['body']??'<p>Оформление доступно в установленном магазине. Эта демонстрация не принимает заказы и оплату.</p><a class="g-button" href="'.$e($href('/catalog/')).'">Вернуться в каталог ↗</a>' ?></section>
        <?php else: ?><section class="g-wrap g-editorial"><span class="g-kicker">404 / СТРАНИЦА НЕ НАЙДЕНА</span><h1>Пойдём<br>за вдохновением.</h1><p>Предмет удалён, ещё не опубликован или адрес изменился.</p><a class="g-button" href="<?= $e($href('/catalog/')) ?>">Открыть каталог ↗</a></section><?php endif ?></main>
        <section class="g-service-strip g-wrap"><a href="<?= $e($href('/delivery/')) ?>"><span>01</span><b>Получить удобно</b><span>Условия доставки ↗</span></a><a href="<?= $e($href('/returns/')) ?>"><span>02</span><b>Выбирать спокойно</b><span>Возврат и обмен ↗</span></a><a href="<?= $e($href('/contact/')) ?>"><span>03</span><b>Спросить напрямую</b><span>Связаться с нами ↗</span></a></section><footer class="g-footer"><div class="g-wrap"><div class="g-footer-top"><a class="g-logo" href="<?= $e($href('/')) ?>"><?= $e($name) ?><small><?= $e(strtoupper($store)) ?> STORE</small></a><p><?= $theme==='market'?'Покупки для каждого дня.':'Ваш дом. Ваш выбор.' ?><br><a class="g-link" href="<?= $e($href('/contact/')) ?>">Связаться с магазином ↗</a></p><nav aria-label="Информация"><a href="<?= $e($href('/catalog/')) ?>">Каталог</a><a href="<?= $e($href('/terms/')) ?>">Условия покупки</a><a href="<?= $e($href('/privacy/')) ?>">Обработка данных</a><a href="<?= $e($href('/contact/')) ?>">Контакты</a><?= Journal::menu($s['footer_menu']??[]) ?></nav></div><div class="g-footer-bottom"><span>© <?= gmdate('Y') ?> <?= $e($name) ?></span><span><?= !empty($o['demo'])?'Иллюстративные товары. Цены — примеры.':'BYPCMS Commerce / '.$store ?></span><a href="<?= $e($href('/account/')) ?>">Мои заказы ↗</a></div></div></footer><dialog class="g-lightbox"><button type="button" aria-label="Закрыть увеличенное фото">Закрыть ×</button><img alt="Увеличенное фото товара"></dialog></body></html><?php
